RoundRobin = 0

LABEL: BEGIN

L0 = getBlockStatus("LPU_0","length")
L1 = getBlockStatus("LPU_1","length")
L2 = getBlockStatus("LPU_2","length")
L3 = getBlockStatus("LPU_3","length")

if ((L0 < L1) && (L0 < L2) && (L0 < L3)) {
    Decision = 0
}
else if ((L1 < L0) && (L1 < L2) && (L1 < L3)) {
    Decision = 1
}
else if ((L2 < L0) && (L2 < L1) && (L2 < L3)) {
    Decision = 2
}
else if ((L3 < L0) && (L3 < L1) && (L3 < L2)) {
    Decision = 3
}
else {
    Decision = RoundRobin
    ++RoundRobin

    if (RoundRobin >= 4) {
        RoundRobin = 0
    }
}

SEND("output", Decision)
